// launch-factory: 관리 화면이 「지금 누구인가」를 읽는 한 곳(계획 3d). 세션과 사용자 행을 요청당 한 번 읽어 판정에 필요한 값만 돌려준다.
// 신원의 모양(signed_out = 로그아웃·만료·읽기 실패, impersonating = 관리자가 대신 들어온 세션, user = 로그인한 사람)은 콘솔 패키지가 정한다.
// 판정(관리자 벽·소유자 규칙·확인 벽)은 여기서 하지 않는다 — 콘솔(@launch-factory/admin-console)이 이 값을 받아 순수하게 정한다. 구획 모듈은 세션을 보지 못한다.
// 입력(요청 본문·주소)의 role·userId 는 읽지 않는다 — 세션의 사용자 행에서만 온다. 서버 전용.
import type { AdminIdentity } from "@launch-factory/admin-console"
import { user } from "@launch-factory/db"
import { eq } from "drizzle-orm"
import { authPort } from "@/lib/launch/auth"
import { database } from "@/lib/launch/db"

export type { AdminIdentity }

/** 세션을 읽고(없으면 signed_out) 사용자 행을 읽는다. 행이 없으면 정지된 사람처럼 권한 없는 사람이다(banned: true) */
export async function identify(): Promise<AdminIdentity> {
  let s: Awaited<ReturnType<Awaited<ReturnType<typeof authPort>>["session"]>>
  try {
    s = await (await authPort()).session()
  } catch {
    return { kind: "signed_out" }
  }
  if (!s.ok || !s.data) return { kind: "signed_out" }
  if (s.data.impersonatedBy) return { kind: "impersonating" }
  const [row] = await (await database()).select({ role: user.role, banned: user.banned, twoFactorEnabled: user.twoFactorEnabled, email: user.email, emailVerified: user.emailVerified }).from(user).where(eq(user.id, s.data.userId)).limit(1)
  if (!row) return { kind: "user", userId: s.data.userId, role: null, banned: true, twoFactor: false, verifiedEmail: null }
  return { kind: "user", userId: s.data.userId, role: row.role ?? null, banned: row.banned === true, twoFactor: row.twoFactorEnabled === true, verifiedEmail: row.emailVerified === true && row.email ? row.email : null }
}

// launch-factory: 관리 콘솔 조립(계획 3d) — 구획 등록부와 AdminPort. 서버 전용. 이 파일은 제품 것이다(레지스트리를 다시 받아도 덮어쓰지 않는다 — 구획을 더하는 자리다).
// 구획 하나 = lib/launch/admin-sections/<id>.ts (defineSection 선언 하나) + 아래 ADMIN_SECTIONS 에 한 줄. 구획이 켜질 부품(part)이 꺼지면(lib/launch/enabled) 사이드바에서도 직접 주소로도 사라진다.
// 콘솔(@launch-factory/admin-console)이 접근 벽(관리자 · 소유자)·사람 확인 벽(confirmed: true)·상태 검사·주소·가리기·기록을 한 곳에서 한다. 여기서는 주입물만 꽂는다:
//   identify  — 세션 + 사용자 행(lib/launch/admin-identity.ts)      limit — 읽기 요청 제한(admin:read 분당 120, 사용자·IP 별). 쓰기 제한은 서버 액션 adminAct 한 곳(분당 30)이 센다 — 여기서 한 번 더 세지 않는다
//   audit     — 표·상세를 읽으면 access_logs 한 줄, 행동을 하면 admin_actions 한 줄(폼 값은 싣지 않는다. 읽기 기록이 실패하면 읽기도 거부)
//   mask      — 연락처 열은 일부만 보이게, 나가는 모든 문구는 이메일·전화·토큰 모양을 가린다
//   onError   — 구획이 던진 오류는 서버 로그에 오류 이름과 위치만(글·개인정보 없음). 화면에는 일반 문구만 나간다
import { headers } from "next/headers"
import { createAdminConsole, hasServerSearch, pageSizeOf, type AdminMasker, type AdminPort, type AdminSection } from "@launch-factory/admin-console"
import { adminActions, insertAccessLog } from "@launch-factory/db"
import { maskPii } from "@launch-factory/security/pii"
import { clientIp, ipAddressFromEnv } from "@launch-factory/security/rate-limit"
import { adminMessages } from "@/content/copy.admin-messages.en"
import { identify } from "@/lib/launch/admin-identity"
import { database } from "@/lib/launch/db"
import { hasPart } from "@/lib/launch/enabled"
import { guardAction } from "@/lib/launch/security"

/**
 * 등록한 구획(순서가 사이드바 순서). 구획 모듈(lib/launch/admin-sections/<id>.ts)에서 구획을 가져와 배열에 한 줄씩 더한다:
 *   ADMIN_SECTIONS = [ordersSection, bookingsSection]
 * 부품 이름(part)은 features/outcomes.yaml parts 의 이름과 같아야 한다 — 시험이 대조한다.
 */
export const ADMIN_SECTIONS: readonly AdminSection[] = []

const MASK = "***"

/** 연락처를 알아볼 만큼만 보인다: 메일 k***@example.com · 전화 ***-1234 · 그 밖(주소)은 앞 낱말만 */
export function maskContact(value: string): string {
  const v = value.trim()
  if (v === "") return v
  const at = v.indexOf("@")
  if (at > 0) return `${[...v][0]}${MASK}${v.slice(at)}`
  const digits = v.replace(/\D/g, "")
  if (digits.length >= 8 && /^[+\d\s().-]+$/.test(v)) return `${MASK}-${digits.slice(-4)}`
  // 낱말이 하나뿐이면 이름일 수 있다("홍길동") — 첫 글자만 보인다. 낱말이 여럿이면(주소) 앞 낱말만 보인다
  const words = v.split(/\s+/)
  return words.length === 1 ? `${Array.from(v)[0]}${MASK}` : `${words[0]} ${MASK}`
}

const masker: AdminMasker = { contact: maskContact, text: maskPii }

async function requester(): Promise<{ headers: Headers; ip: string }> {
  const h = new Headers(await headers())
  return { headers: h, ip: clientIp(h, ipAddressFromEnv(process.env)) ?? "unknown" }
}

/** 이 구획의 검색을 서버가 가린 연락처 칸까지 맞추는가(구획의 serverSearch 선언) — 목록 쪽이 받은 행을 다시 거르지 않게 한다 */
export const searchesOnServer = (id: string): boolean => hasServerSearch(ADMIN_SECTIONS, id)

/** 이 구획의 한 쪽 줄 수(구획의 pageSize 선언, 없으면 100) — 쪽 이동이 몇 쪽까지 있는지 셀 때 쓴다 */
export const pageSizeFor = (id: string): number => pageSizeOf(ADMIN_SECTIONS, id)

let cached: AdminPort | undefined

/** 등록한 구획으로 만든 콘솔(요청마다 새로 만들지 않는다 — 신원은 포트 호출마다 한 번 읽는다) */
export function adminConsole(): AdminPort {
  return (cached ??= createAdminConsole({
    sections: ADMIN_SECTIONS,
    identify,
    messages: adminMessages,
    enabledParts: [...new Set(ADMIN_SECTIONS.map((s) => s.part))].filter(hasPart),
    mask: masker,
    limit: async (kind, actor) => (kind === "read" ? guardAction("admin:read", { headers: (await requester()).headers, userId: actor.userId }) : null),
    audit: {
      async access(r) {
        const { ip } = await requester()
        await insertAccessLog(await database(), { actorId: r.actorId, ip, subjects: r.ids, action: "view", target: `admin/${r.section}/${r.kind}`, occurredAt: r.at.toISOString(), download: false })
      },
      async action(r) {
        const { ip } = await requester()
        await (await database()).insert(adminActions).values({ adminUserId: r.actorId, action: `${r.section}.${r.action}`, ipAddress: ip, meta: { section: r.section, recordId: r.id, ok: r.ok, via: r.via, ...(r.code ? { code: r.code } : {}) }, occurredAt: r.at })
      },
    },
    onError: (error, where) => console.error(`[admin] ${where}: ${error instanceof Error ? error.name : "error"}`),
  }))
}

"use server"
// launch-factory: 관리 화면의 서버 액션 다섯(계획 3d) = 포트 AdminPort 의 모양: adminSections · adminOverview · adminTable · adminRecord · adminAct.
// 서버 액션은 누구나 직접 POST 로 부를 수 있다 — 그래서 모든 입구가 세션을 먼저 읽는다(없으면 sign_in_required). 이 파일은 로그인 여부만 보고 포트(콘솔)에 넘긴다.
// 이 사람이 이 구획을 쓸 수 있는지(관리자 벽·소유자 규칙)와 사람 확인 벽(confirmed: true)은 콘솔이 신원(lib/launch/admin-identity.ts)으로 정한다 — 입력의 role·userId 는 읽지 않는다.
// 행동(adminAct)은 요청 제한(adminAct, 분당 30)을 먼저 지난다 — 쓰기 제한은 이 한 곳뿐이다(콘솔은 읽기만 센다). 던진 오류는 콘솔이 일반 실패로 바꿔 돌려준다(DB 글·개인정보가 화면에 나가지 않는다).
import { headers } from "next/headers"
import type { AdminActInput, AdminActOutcome, AdminOverview, AdminRecord, AdminResult, AdminSectionInfo, AdminTable, AdminTableQuery } from "@launch-factory/admin-console"
import { signInRequiredResult } from "@launch-factory/security/action"
import { adminConsole } from "@/lib/launch/admin-console"
import { authPort } from "@/lib/launch/auth"
import { DEFAULT_LOCALE } from "@/lib/launch/config"
import { guardAction } from "@/lib/launch/security"

/** 지금 로그인한 사람. 로그아웃·만료·읽기 실패는 null */
async function actor(): Promise<{ userId: string } | null> {
  const s = await (await authPort()).session()
  return s.ok && s.data ? { userId: s.data.userId } : null
}

const signInRequired = () => signInRequiredResult(DEFAULT_LOCALE)

/** 사이드바에 보일 구획 목록(이 사람이 볼 수 있는 것만) */
export async function adminSections(): Promise<AdminResult<AdminSectionInfo[]>> {
  if (!(await actor())) return signInRequired()
  return adminConsole().sections()
}

/** 개요: 지금 처리할 일 + 최근 변화(구획들이 보탠 것을 합친다) */
export async function adminOverview(): Promise<AdminResult<AdminOverview>> {
  if (!(await actor())) return signInRequired()
  return adminConsole().overview()
}

/** 입력: { section, search?, status?, limit? } — 최근 순, limit 은 1~200(기본 100) */
export async function adminTable(input: { section: string } & AdminTableQuery): Promise<AdminResult<AdminTable>> {
  if (!(await actor())) return signInRequired()
  return adminConsole().table(input)
}

/** 입력: { section, id } */
export async function adminRecord(input: { section: string; id: string }): Promise<AdminResult<AdminRecord>> {
  if (!(await actor())) return signInRequired()
  return adminConsole().record(input)
}

/** 입력: { section, id, action, fields?, confirmed? } — 확인이 필요한 행동(confirmActions)은 confirmed: true 가 있어야 실행된다 */
export async function adminAct(input: AdminActInput): Promise<AdminResult<AdminActOutcome>> {
  const who = await actor()
  if (!who) return signInRequired()
  const refused = await guardAction("adminAct", { headers: new Headers(await headers()), userId: who.userId })
  if (refused) return refused
  return adminConsole().act(input)
}

// launch-factory: DB 연결. mock 은 메모리 PGlite(키 없이 켜진다), live 는 DATABASE_URL(Supabase 풀러 6543 — prepared statement 끔은 패키지가 한다).
// mock 의 마이그레이션은 이 앱에 설치된 db/migrations 를 쓴다(번들 안에서는 패키지 폴더를 찾을 수 없다).
import { join } from "node:path"
import { db, type Database } from "@launch-factory/db"
import { env, required } from "@/lib/launch/env"

let cached: Promise<Database> | undefined

/**
 * mock 의 메모리 DB 는 프로세스 하나에 하나다. 서버 번들은 쪽·서버 액션·경로 처리기(app/api)로 갈라져 같은 모듈이 번들마다 따로 불리므로(Next/Turbopack),
 * 모듈 변수에만 두면 번들 수만큼 DB 가 생겨 경로 처리기(웹훅·크론·/api/auth)와 쪽이 서로 다른 데이터를 보았다(관리 화면 시험 실측: 경로로 만든 세션이 쪽에서 안 보였다).
 * 그래서 globalThis 에 둔다. live 는 연결 문자열이 같은 DB 를 가리키므로 모듈 변수로 충분하다.
 */
const mockStore = globalThis as { __lfMockDb?: Promise<Database> }

export function database(): Promise<Database> {
  if (env().LF_MODE === "mock") return (mockStore.__lfMockDb ??= db.local({ migrationsFolder: join(process.cwd(), "db", "migrations") }))
  return (cached ??= Promise.resolve(db(required("DATABASE_URL"))))
}

// launch-factory: 환경 읽기. 이름만 다루고 값은 어디에도 남기지 않는다.
// LF_MODE 는 항상 필수다 — 없으면 켜지지 않는다(조용히 mock 으로 가지 않는다). live 에서는 공급자 키가 모두 필수다.
import { loadAppEnv, type AppEnv } from "@launch-factory/env"

let cached: AppEnv | undefined

/** 처음 부를 때 한 번 검사한다. 빠진 이름은 모두 모아 한 번에 알린다(값은 싣지 않는다). */
export function env(): AppEnv {
  return (cached ??= loadAppEnv())
}

/** 설정값·비밀값 하나를 읽는다. 없으면 이름만 담아 던진다. */
export function required(name: string): string {
  const value = (env() as Record<string, string | undefined>)[name] ?? process.env[name]
  if (!value) throw new Error(`${name} is not set (see .env.example)`)
  return value
}

/** 없어도 되는 설정값. */
export function optional(name: string): string | undefined {
  return process.env[name] || undefined
}

// launch-factory: 제품마다 고치는 값. 이 파일은 제품 것이다 — 레지스트리를 다시 받으면 덮어쓸지 묻는다.
import type { Locale } from "@launch-factory/email"
import { env, required } from "@/lib/launch/env"

export const PRODUCT_NAME = "My Product"
/** 사용자 칸(user.locale)이 비었을 때 메일·오류 문구의 언어 */
export const DEFAULT_LOCALE: Locale = "en"
/** 가입 때 동의 기록에 남길 약관·개인정보 처리방침의 판. 문서를 고치면 올린다 */
export const CONSENT_VERSIONS = { terms: "2026-09-30", privacy: "2026-09-30" }
/** 결제 메일이 가리키는 화면 경로 */
export const ROUTES = { billing: "/account/billing", acceptPriceChange: "/account/billing/price-change", decline: "/account/billing/cancel", security: "/forgot-password", contact: "/contact" }

/** 앱 주소. mock 에서는 로컬 주소로 켜지고, live 에서는 NEXT_PUBLIC_APP_URL 이 필수다 */
export function appUrl(): string {
  // 빈 문자열은 없는 것으로 본다 — shadcn CLI 가 envVars 이름을 `NAME=`(빈 값)으로 .env.local 에 적는다
  return process.env.NEXT_PUBLIC_APP_URL || (env().LF_MODE === "mock" ? "http://localhost:3000" : required("NEXT_PUBLIC_APP_URL"))
}
